from pathlib import Path

ROOT = Path(__file__).resolve().parent
STATIC = ROOT / "static"

STOCK_FIX = '(()=>{\n\'use strict\';\nconst $=id=>document.getElementById(id);\nconst parts=location.pathname.split(\'/\').filter(Boolean),MARKET=(parts[1]||\'KR\').toUpperCase(),CODE=(parts[2]||\'\').toUpperCase();\nconst num=v=>Number(v||0);\nconst esc=s=>String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#039;\'}[c]));\nconst qty=v=>{const n=num(v),a=Math.abs(n),sg=n>0?\'+\':n<0?\'−\':\'\';if(a>=1e8)return sg+(a/1e8).toFixed(2)+\'억주\';if(a>=1e4)return sg+(a/1e4).toFixed(1)+\'만주\';return sg+Math.round(a).toLocaleString(\'ko-KR\')+\'주\'};\nconst sdate=v=>{const s=String(v||\'\').replace(/\\D/g,\'\');return s.length>=8?`${s.slice(4,6)}/${s.slice(6,8)}`:String(v||\'\')};\n\nconst style=document.createElement(\'style\');\nstyle.textContent=`\n.v348-disc-strip{margin:10px 0 8px;padding:10px 12px;border:1px solid rgba(135,158,190,.18);border-radius:12px;background:rgba(8,18,34,.42)}\n.v348-disc-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:8px;font-size:12px;color:#93a6bf}.v348-disc-head b{color:#d8e5f5}\n.v348-disc-items{display:flex;gap:7px;overflow-x:auto;padding-bottom:2px;scrollbar-width:thin}\n.v348-disc-chip{min-width:155px;max-width:240px;border:1px solid rgba(130,154,188,.18);border-radius:10px;padding:8px 9px;background:rgba(15,28,49,.62);text-decoration:none;color:#dbe7f4;display:block}\n.v348-disc-chip small{display:block;color:#7f95ae;margin-bottom:4px}.v348-disc-chip span{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px}\n.v348-disc-chip.pos{border-color:rgba(17,184,132,.42)}.v348-disc-chip.neg{border-color:rgba(239,99,121,.42)}\n.v348-chart-event-overlay{position:absolute;inset:0;pointer-events:none;z-index:3}\n.v348-flow-legend{display:flex;gap:12px;flex-wrap:wrap;margin:6px 0 0;font-size:11px;color:#8fa2bb}.v348-flow-legend i{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:4px}\n.v348-flow-legend .f i{background:#4ea1ff}.v348-flow-legend .i i{background:#a975ff}.v348-flow-legend .p i{background:#f0a44b}`;\ndocument.head.appendChild(style);\n\nlet disclosureRows=[],dailyBars=[];\n\nfunction installDisclosureUI(){\n const wrap=$(\'candleWrap\'); if(!wrap)return;\n if(!document.querySelector(\'.v348-disc-strip\')){\n  const strip=document.createElement(\'div\');strip.className=\'v348-disc-strip\';\n  strip.innerHTML=\'<div class="v348-disc-head"><b>차트 공시</b><span id="v348DiscStatus">공시 확인 중</span></div><div id="v348DiscItems" class="v348-disc-items"></div>\';\n  wrap.parentElement.insertBefore(strip,wrap);\n }\n if(!$(\'v348ChartEvents\')){\n  const ov=document.createElement(\'canvas\');ov.id=\'v348ChartEvents\';ov.className=\'v348-chart-event-overlay\';wrap.appendChild(ov);\n }\n}\n\nfunction drawDisclosureOverlay(){\n const ov=$(\'v348ChartEvents\'),base=$(\'candleCanvas\');if(!ov||!base)return;\n const dpr=Math.max(1,window.devicePixelRatio||1),w=base.clientWidth,h=base.clientHeight;\n ov.width=Math.round(w*dpr);ov.height=Math.round(h*dpr);ov.style.width=w+\'px\';ov.style.height=h+\'px\';\n const cx=ov.getContext(\'2d\');cx.setTransform(dpr,0,0,dpr,0,0);cx.clearRect(0,0,w,h);\n const tf=document.querySelector(\'[data-tf].active\')?.dataset.tf||\'1d\';if(tf!==\'1d\'||!dailyBars.length||!disclosureRows.length)return;\n const visible=dailyBars.slice(-Math.min(42,dailyBars.length)),padL=12,padR=w<520?58:72,step=(w-padL-padR)/visible.length;\n const byDate=new Map();visible.forEach((b,i)=>byDate.set(String(b.time||b.date||\'\').replace(/\\D/g,\'\').slice(0,8),i));\n disclosureRows.slice(0,20).forEach((e,idx)=>{\n  const ds=String(e.date||\'\').replace(/\\D/g,\'\').slice(0,8),i=byDate.get(ds);if(i==null)return;\n  const x=padL+step*i+step/2,y=10+(idx%2)*15,positive=e.sentiment===\'positive\';\n  cx.fillStyle=positive?\'#11b884\':e.sentiment===\'negative\'?\'#ef6379\':\'#d9a441\';\n  cx.beginPath();cx.moveTo(x,y+8);cx.lineTo(x-5,y);cx.lineTo(x+5,y);cx.closePath();cx.fill();\n  cx.font=\'9px system-ui\';cx.textAlign=\'center\';cx.fillText(\'공시\',x,y+19);\n });\n}\n\nasync function refreshDisclosures(){\n installDisclosureUI();const box=$(\'v348DiscItems\'),st=$(\'v348DiscStatus\');if(!box||!st)return;\n try{\n  const [er,sr]=await Promise.all([\n   fetch(`/api/v344/disclosures/${MARKET}/${encodeURIComponent(CODE)}?months=3`,{cache:\'no-store\'}),\n   fetch(`/api/v344/stock/${MARKET}/${encodeURIComponent(CODE)}?timeframe=1d&days=60`,{cache:\'no-store\'})\n  ]);\n  if(!er.ok)throw new Error(`HTTP ${er.status}`);\n  const e=await er.json();disclosureRows=(e.items||[]).slice(0,20);\n  if(sr.ok){const sd=await sr.json();dailyBars=(sd.bars||[]).slice(-60)}\n  st.textContent=`${e.source||(MARKET===\'KR\'?\'DART\':\'SEC\')} · ${disclosureRows.length}건`;\n  box.innerHTML=disclosureRows.length?disclosureRows.slice(0,12).map(x=>`<a class="v348-disc-chip ${x.sentiment===\'positive\'?\'pos\':x.sentiment===\'negative\'?\'neg\':\'\'}" ${x.url?`href="${esc(x.url)}" target="_blank" rel="noopener"`:\'\'}><small>${esc(x.date||\'\')} · ${esc(x.label||x.form||\'공시\')}</small><span title="${esc(x.title||\'\')}">${esc(x.title||\'-\')}</span></a>`).join(\'\'):\'<span style="color:#7f91a9;font-size:12px">최근 3개월 공식 공시 없음</span>\';\n  drawDisclosureOverlay();\n }catch(e){st.textContent=\'공시 연결 대기\'}\n}\n\nfunction installSharedFlow(){\n if(MARKET!==\'KR\')return null;const old=$(\'investorFlowCanvas\');if(!old)return null;\n if(old.dataset.v348===\'1\')return old;\n const fresh=old.cloneNode(false);fresh.id=\'investorFlowCanvas\';fresh.dataset.v348=\'1\';old.replaceWith(fresh);\n const desc=document.querySelector(\'#investorFlowPanel .v346-section-head p\');if(desc)desc.textContent=\'외국인·기관·개인을 같은 Y축으로 비교해 상대 규모와 방향을 그대로 확인합니다.\';\n const foot=document.querySelector(\'#investorFlowPanel .v346-chart-foot span:first-child\');if(foot)foot.textContent=\'일별 순매수(주) · 공통 Y축 · 0선 기준 매수 + / 매도 −\';\n const summary=$(\'investorFlowSummary\');if(summary&&!document.querySelector(\'.v348-flow-legend\')){const l=document.createElement(\'div\');l.className=\'v348-flow-legend\';l.innerHTML=\'<span class="f"><i></i>외국인</span><span class="i"><i></i>기관</span><span class="p"><i></i>개인</span>\';summary.after(l)}\n return fresh;\n}\nfunction drawSharedFlow(canvas,rows){\n const ctx=canvas.getContext(\'2d\'),r=canvas.parentElement.getBoundingClientRect(),dpr=Math.max(1,window.devicePixelRatio||1),w=Math.max(1,Math.round(r.width)),h=Math.max(1,Math.round(r.height));\n canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);canvas.style.width=w+\'px\';canvas.style.height=h+\'px\';ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);\n if(!rows.length){ctx.fillStyle=\'#7f91a9\';ctx.font=\'12px system-ui\';ctx.fillText(\'최근 20거래일 수급 데이터 축적 중\',18,30);return}\n const keys=[\'foreign\',\'institution\',\'person\'],cols=[\'#4ea1ff\',\'#a975ff\',\'#f0a44b\'],pad={l:w<520?64:78,r:14,t:16,b:34},cw=w-pad.l-pad.r,mid=pad.t+(h-pad.t-pad.b)/2,maxAbs=Math.max(1,...rows.flatMap(x=>keys.map(k=>Math.abs(num(x[k]))))),scale=((h-pad.t-pad.b)*.43)/maxAbs,step=cw/rows.length,groupW=Math.max(7,Math.min(24,step*.72)),barW=Math.max(2,groupW/3-1);\n ctx.strokeStyle=\'rgba(135,158,190,.28)\';ctx.beginPath();ctx.moveTo(pad.l,mid);ctx.lineTo(w-pad.r,mid);ctx.stroke();ctx.font=\'10px system-ui\';ctx.fillStyle=\'#7e91aa\';ctx.textAlign=\'right\';ctx.fillText(qty(maxAbs).replace(\'+\',\'\'),pad.l-7,pad.t+4);ctx.fillText(\'0\',pad.l-7,mid+3);ctx.fillText(qty(-maxAbs),pad.l-7,h-pad.b);\n rows.forEach((row,i)=>{const gx=pad.l+step*i+step/2;keys.forEach((k,j)=>{const v=num(row[k]),hh=Math.abs(v)*scale,x=gx-groupW/2+j*(barW+1);ctx.fillStyle=cols[j];ctx.globalAlpha=.78;ctx.fillRect(x,v>=0?mid-hh:mid,barW,Math.max(1,hh));ctx.globalAlpha=1});if(i%Math.max(1,Math.ceil(58/Math.max(1,step)))===0||i===rows.length-1){ctx.fillStyle=\'#6f829d\';ctx.textAlign=\'center\';ctx.fillText(sdate(row.date),gx,h-10)}});ctx.textAlign=\'left\';canvas._v348={rows,pad,step};\n}\nasync function refreshSharedFlow(){\n if(MARKET!==\'KR\')return;const canvas=installSharedFlow();if(!canvas)return;\n try{\n  const r=await fetch(`/api/v344/investor-stock/${encodeURIComponent(CODE)}`,{cache:\'no-store\'});if(!r.ok)throw new Error(`HTTP ${r.status}`);\n  const d=await r.json(),rows=(d.items||[]).slice(-20);drawSharedFlow(canvas,rows);\n  const st=$(\'investorFlowStatus\');if(st)st.textContent=`${rows.length}/20거래일 · ${d.source||\'NHPLUG\'} · 공통축 비교`;\n  canvas.onmousemove=e=>{const v=canvas._v348;if(!v)return;const rr=canvas.getBoundingClientRect(),x=e.clientX-rr.left,i=Math.max(0,Math.min(v.rows.length-1,Math.floor((x-v.pad.l)/v.step))),row=v.rows[i],tip=$(\'investorFlowTooltip\');if(!row||!tip)return;tip.classList.remove(\'hide\');tip.style.left=Math.min(rr.width-220,Math.max(8,x+12))+\'px\';tip.style.top=\'14px\';tip.innerHTML=`<b>${esc(row.date||\'\')}</b><span>외국인 ${qty(row.foreign)}</span><span>기관 ${qty(row.institution)}</span><span>개인 ${qty(row.person)}</span>`};\n  canvas.onmouseleave=()=>$(\'investorFlowTooltip\')?.classList.add(\'hide\');\n }catch(e){drawSharedFlow(canvas,[])}\n}\n\ninstallDisclosureUI();refreshDisclosures();refreshSharedFlow();\ndocument.querySelectorAll(\'[data-tf]\').forEach(b=>b.addEventListener(\'click\',()=>setTimeout(drawDisclosureOverlay,250)));\n$(\'candleCanvas\')?.addEventListener(\'wheel\',()=>{$(\'v348ChartEvents\').style.opacity=\'0\'});\n$(\'candleCanvas\')?.addEventListener(\'mousedown\',()=>{$(\'v348ChartEvents\').style.opacity=\'0\'});\n$(\'candleCanvas\')?.addEventListener(\'dblclick\',()=>setTimeout(()=>{const o=$(\'v348ChartEvents\');if(o)o.style.opacity=\'1\';drawDisclosureOverlay()},250));\nsetInterval(refreshDisclosures,120000);setInterval(refreshSharedFlow,30000);\nwindow.addEventListener(\'resize\',()=>setTimeout(()=>{refreshSharedFlow();drawDisclosureOverlay()},100));\n})();'
INDEX_FIX = '(()=>{\n\'use strict\';\nconst parts=location.pathname.split(\'/\').filter(Boolean),MARKET=(parts[1]||\'KR\').toUpperCase(),KEY=(parts[2]||\'\').toLowerCase();\nconst num=v=>Number(v||0),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));\nfunction pct(v){const n=num(v);return (n>0?\'+\':\'\')+n.toFixed(2)+\'%\'}\nfunction install(){\n const row=document.querySelector(\'.v346-index-status-row\');if(!row||document.getElementById(\'v348IndexJudgment\'))return;\n const card=document.createElement(\'div\');card.id=\'v348IndexJudgment\';card.innerHTML=\'<small>AI 지수판단</small><b id="v348IndexJudgmentText">계산 중</b><span id="v348IndexJudgmentMeta" style="display:block;margin-top:4px;font-size:11px;color:#7f91a9"></span>\';row.appendChild(card);\n}\nfunction judge(d){\n const bars=(d.bars||[]).filter(x=>num(x.close)>0),c=bars.map(x=>num(x.close));if(c.length<10)return {label:\'데이터 축적 중\',score:null,meta:`일봉 ${c.length}개`};\n const last=c.at(-1),ma5=c.slice(-5).reduce((a,b)=>a+b,0)/5,ma20=c.slice(-Math.min(20,c.length)).reduce((a,b)=>a+b,0)/Math.min(20,c.length);\n const r5=c.length>=6?(last/c.at(-6)-1)*100:0,r20=c.length>=21?(last/c.at(-21)-1)*100:0,day=num(d.change_pct);\n let score=50;score+=clamp(day*5,-18,18);score+=clamp(r5*2.5,-15,15);score+=ma5>ma20?10:-10;score+=last>ma20?7:-7;score+=clamp(r20, -8, 8);score=clamp(score,0,100);\n const label=score>=72?\'강한 상승 우세\':score>=58?\'상승 우세\':score>42?\'중립/혼조\':score>28?\'하락 우세\':\'강한 하락 우세\';\n return {label,score:Math.round(score),meta:`당일 ${pct(day)} · 5일 ${pct(r5)} · 20일 ${pct(r20)}`};\n}\nasync function refresh(){\n install();try{const r=await fetch(`/api/v344/index/${MARKET}/${encodeURIComponent(KEY)}?days=60`,{cache:\'no-store\'});if(!r.ok)throw new Error(`HTTP ${r.status}`);const d=await r.json(),j=judge(d),t=document.getElementById(\'v348IndexJudgmentText\'),m=document.getElementById(\'v348IndexJudgmentMeta\');if(t)t.textContent=j.score==null?j.label:`${j.label} · ${j.score}`;if(m)m.textContent=j.meta}catch(e){const t=document.getElementById(\'v348IndexJudgmentText\');if(t)t.textContent=\'판단 데이터 대기\'}\n}\ninstall();refresh();setInterval(refresh,30000);\n})();'

def _write(name, text):
    try:
        STATIC.mkdir(parents=True, exist_ok=True)
        (STATIC / name).write_text(text, encoding="utf-8")
    except Exception:
        pass

def _inject(html_name, script_name):
    try:
        p = STATIC / html_name
        if not p.exists():
            return
        text = p.read_text(encoding="utf-8")
        marker = f"/static/{script_name}"
        if marker not in text:
            text = text.replace("</body>", f'  <script src="{marker}?v=348"></script>\n</body>')
            p.write_text(text, encoding="utf-8")
    except Exception:
        pass

_write("stock-fix.js", STOCK_FIX)
_write("index-fix.js", INDEX_FIX)
_inject("stock.html", "stock-fix.js")
_inject("index-detail.html", "index-fix.js")
